using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using Racer;using Object=UnityEngine.Object;
public static class AuditSeven {
 public static string Main(){var rows=new List<string>();Directory.CreateDirectory("Docs/SevenCorrections");foreach(var scene in new[]{"DansBackyardReverse","LakeWoods"}){EditorSceneManager.OpenScene("Assets/Scenes/"+scene+".unity");Physics.SyncTransforms();rows.Add(scene);var race=Object.FindAnyObjectByType<RaceDirector>();race.road.Initialize();foreach(var b in Object.FindObjectsByType<WoodlandRoute>()){rows.Add($"BRANCH {b.title} length={b.Length} underground={b.undergroundStart}-{b.undergroundEnd} ai={b.aiValidated} start={b.points[0]} end={b.points[^1]}");if(scene.StartsWith("Dans")){for(float s=b.title.StartsWith("Storm")?0:b.Length-65;s<= (b.title.StartsWith("Storm")?45:b.Length);s+=2){var p=b.At(s,out var f);var hits=Physics.RaycastAll(p+Vector3.up*4,Vector3.down,12,~0,QueryTriggerInteraction.Ignore).Where(h=>!h.collider.transform.IsChildOf(race.vehicle.transform)).OrderBy(h=>h.distance);rows.Add($"PROFILE {b.title} s={s:F2} p={p:F3} grade={f.y/Mathf.Max(.01f,new Vector2(f.x,f.z).magnitude):F3} hits="+string.Join(";",hits.Select(h=>$"{h.collider.name}:{h.point.y:F3}:{h.normal:F2}")));}}}
foreach(var p in scene.StartsWith("Dans")?new[]{new Vector3(172.1f,66,86.2f),new Vector3(405.4f,80.5f,2.5f)}:new Vector3[0]){rows.Add("COORD "+p);foreach(var c in Physics.OverlapBox(p,new Vector3(9,10,9)))rows.Add($"OBJECT {c.name} parent={c.transform.parent?.name} bounds={c.bounds} mesh={AssetDatabase.GetAssetPath((c.GetComponent<MeshFilter>()?c.GetComponent<MeshFilter>().sharedMesh:null))}");float s=race.road.Project(p,out _);for(float d=-30;d<45;d+=2){var q=race.road.At(s+d,out _);rows.Add($"MAIN {s+d:F2} {q:F3} "+string.Join(";",Physics.RaycastAll(q+Vector3.up*10,Vector3.down,25,1,QueryTriggerInteraction.Ignore).OrderBy(h=>h.distance).Select(h=>$"{h.collider.name}:{h.point.y:F3}")));}}
if(scene=="LakeWoods")foreach(var r in Object.FindObjectsByType<Renderer>().Where(r=>r.name.Contains("Cave")||r.name.Contains("cave")))rows.Add($"CAVE {r.name} bounds={r.bounds} mesh={AssetDatabase.GetAssetPath((r.GetComponent<MeshFilter>()?r.GetComponent<MeshFilter>().sharedMesh:null))}");
}File.WriteAllLines("Docs/SevenCorrections/baseline.txt",rows);EditorSceneManager.OpenScene("Assets/Scenes/DansBackyardReverse.unity");return "Baseline written";}}


